});

afterEach(() => {
  limparBanco(db);
  db.close();
  clock.definirAgora(null);
});

function agendar(ator, overrides = {}) {
  return servicos.consultasService.agendar(ator, {
    pacienteId: pacienteAna.id,
    medicoId: medicoCarlos.id,
    inicio: '2026-10-20 10:00',
